// VectorDistanceFunctions: Velox scalar function registration for vector
// distance functions (l2_distance, cosine_distance, inner_product).
//
// Wraps the SIMD-optimized VectorDistance.h functions as Velox VectorFunctions
// so they can be called from Substrait plans generated by the Java planner.
//
// Signature: (ARRAY<DOUBLE>, ARRAY<DOUBLE>) -> DOUBLE
//
// Placement: vector/ — Native vector index computation components.
#pragma once

namespace pangrova::vector {

// Register l2_distance, cosine_distance, and inner_product as Velox
// scalar VectorFunctions. Must be called during runtime initialization
// (after Velox Presto functions are registered).
void registerVectorDistanceFunctions();

}  // namespace pangrova::vector
